<section class="expertise-section" id="skills">
  <div class="container">
    <div class="section-header">
      <h2>My Expertise</h2>
      <p class="subtitle">A hybrid professional combining deep petroleum engineering domain knowledge<br>with modern data analytics & visualization capabilities – delivering actionable insights in the Digital Oilfield era.</p>
    </div>

    <div class="skills-grid">
      <!-- Petroleum Engineering Column -->
      <div class="skill-category petro">
        <h3>Petroleum Engineering Expertise</h3>
        <div class="skill-list">
          <div class="skill-item"><i class="fas fa-oil-can"></i> Reservoir Characterization & Simulation</div>
          <div class="skill-item"><i class="fas fa-chart-line"></i> Production Optimization & Forecasting</div>
          <div class="skill-item"><i class="fas fa-tachometer-alt"></i> Decline Curve Analysis (Arps, Duong, SEPD)</div>
          <div class="skill-item"><i class="fas fa-flask"></i> PVT Analysis & Correlation Development</div>
          <div class="skill-item"><i class="fas fa-water"></i> Enhanced Oil Recovery (EOR) Screening & Evaluation</div>
          <div class="skill-item"><i class="fas fa-project-diagram"></i> Field Development Planning (FDP)</div>
          <div class="skill-item"><i class="fas fa-tools"></i> History Matching & Model Calibration</div>
          <div class="skill-item"><i class="fas fa-hard-hat"></i> Well Test Interpretation & Pressure Transient Analysis</div>
          <div class="skill-item"><i class="fas fa-database"></i> Reservoir Data Analysis & Uncertainty Modeling</div>
        </div>
      </div>

      <!-- Data Analytics Column -->
      <div class="skill-category data">
        <h3>Data Analytics & Digital Tools</h3>
        <div class="skill-list">
          <div class="skill-item"><i class="fab fa-python"></i> Python (Pandas, NumPy, Matplotlib, Seaborn) – Advanced</div>
          <div class="skill-item"><i class="fas fa-database"></i> SQL (Complex Queries, CTEs, Window Functions, Optimization)</div>
          <div class="skill-item"><i class="fas fa-chart-pie"></i> Power BI (DAX, Power Query, Interactive Dashboards) – Advanced</div>
          <div class="skill-item"><i class="fas fa-table"></i> Tableau – Intermediate</div>
          <div class="skill-item"><i class="fas fa-file-excel"></i> Advanced Excel (Pivot Tables, VBA, Power Pivot, Macros)</div>
          <div class="skill-item"><i class="fas fa-brain"></i> Predictive Modeling & Statistical Analysis</div>
          <div class="skill-item"><i class="fas fa-search"></i> Data Cleaning, ETL & Feature Engineering</div>
          <div class="skill-item"><i class="fas fa-sitemap"></i> RFM Segmentation & Customer Analytics</div>
          <div class="skill-item"><i class="fas fa-vial"></i> t-Navigator (Model Building, History Matching, Forecasting)</div>
          <div class="skill-item"><i class="fas fa-code"></i> Google Colab, VS Code, Git & GitHub</div>
        </div>
      </div>
    </div>

    <!-- Bonus: Emerging Skills -->
    <div class="emerging-skills">
      <p><strong>Currently Strengthening:</strong> Machine Learning basics (Scikit-learn), Streamlit for web apps, Azure/AWS fundamentals</p>
    </div>
  </div>
</section>

css:
.expertise-section {
  background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%);
  padding: 120px 0;
  color: white;
}

.section-header {
  text-align: center;
  margin-bottom: 60px;
}

.section-header h2 {
  font-size: 3rem;
  margin-bottom: 16px;
  background: linear-gradient(to right, #f59e0b, #fbbf24);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.subtitle {
  font-size: 1.25rem;
  opacity: 0.9;
  max-width: 900px;
  margin: 0 auto;
  line-height: 1.6;
}

.skills-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(500px, 1fr));
  gap: 50px;
  max-width: 1200px;
  margin: 0 auto;
}

.skill-category {
  background: rgba(255,255,255,0.05);
  padding: 40px;
  border-radius: 20px;
  backdrop-filter: blur(10px);
  border: 1px solid rgba(251,191,36,0.2);
}

.skill-category h3 {
  font-size: 1.8rem;
  margin-bottom: 30px;
  color: #f59e0b;
  text-align: center;
}

.skill-list {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.skill-item {
  font-size: 1.1rem;
  display: flex;
  align-items: center;
  gap: 12px;
  transition: transform 0.3s;
}

.skill-item:hover {
  transform: translateX(10px);
  color: #fbbf24;
}

.skill-item i {
  font-size: 1.4rem;
  color: #f59e0b;
  width: 30px;
}

.emerging-skills {
  text-align: center;
  margin-top: 60px;
  font-size: 1.1rem;
  opacity: 0.8;
}

@media (max-width: 768px) {
  .skills-grid {
    grid-template-columns: 1fr;
    gap: 40px;
  }
  .skill-category {
    padding: 30px;
  }
}

