#header {
  background: rgba(15, 23, 42, 0.95);
  backdrop-filter: blur(10px);
  transition: all 0.5s;
  z-index: 997;
  padding: 20px 0;
  border-bottom: 1px solid rgba(251, 191, 36, 0.1);
}

#header.header-scrolled {
  padding: 15px 0;
  background: rgba(15, 23, 42, 0.98);
  box-shadow: 0 5px 20px rgba(0,0,0,0.3);
}

.logo {
  font-size: 2rem;
  font-weight: 700;
  margin: 0;
}

.logo span { color: white; }
.logo span span { color: #f59e0b; }

.navbar ul {
  margin: 0;
  padding: 0;
  display: flex;
  list-style: none;
  align-items: center;
}

.navbar li {
  margin-left: 35px;
}

.navbar a, .navbar a:focus {
  color: #cbd5e1;
  font-size: 1.1rem;
  font-weight: 500;
  transition: 0.3s;
}

.navbar a:hover, .navbar .active {
  color: #f59e0b;
}

.getstarted {
  background: #f59e0b;
  color: white !important;
  padding: 10px 25px !important;
  border-radius: 50px;
  border: 2px solid #f59e0b;
}

.getstarted:hover {
  background: #fbbf24;
  border-color: #fbbf24;
}

.mobile-nav-toggle {
  color: white;
  font-size: 28px;
  cursor: pointer;
  display: none;
}

@media (max-width: 991px) {
  .mobile-nav-toggle { display: block; }
  .navbar ul { display: none; }
  .navbar.mobile-active ul {
    display: block;
    position: fixed;
    top: 80px;
    left: 0;
    width: 100%;
    background: #0f172a;
    padding: 20px;
  }
}
